method Strongest_Extension(class_name: string, extensions: seq<string>) returns (result: string)
    requires class_name != null && extensions != null
    requires |extensions| > 0
    requires forall e: string :: e in extensions ==> e != null
    ensures result == class_name + "." + strongest_extension_name
    ensures strongest_extension_name in extensions
    ensures forall e: string :: e in extensions && e != strongest_extension_name ==> (strength(e) < strength(strongest_extension_name) || 
            (strength(e) == strength(strongest_extension_name) && e != strongest_extension_name))
{
    var strongest_extension_name := "";
    var max_strength := -999; // Initialize to a low number to find the maximum

    // Loop through each extension to find the strongest one
    var i := 0;
    while i < |extensions|
        invariant 0 <= i <= |extensions|
        invariant max_strength == -999 || (strongest_extension_name in extensions && 
            strength(strongest_extension_name) == max_strength) // strongest_extension_name is the best found so far
    {
        var current_extension := extensions[i];
        var current_strength := strength(current_extension);

        if current_strength > max_strength {
            max_strength := current_strength;
            strongest_extension_name := current_extension;
        }

        i := i + 1;
    }

    result := class_name + "." + strongest_extension_name;
}

// Helper function to compute the strength of an extension
function method strength(extension: string) returns (s: int)
{
    var cap := 0;
    var sm := 0;

    var i := 0;
    while i < extension.Length
        invariant 0 <= i <= extension.Length
    {
        if extension[i] >= 'A' && extension[i] <= 'Z' {
            cap := cap + 1;
        } else if extension[i] >= 'a' && extension[i] <= 'z' {
            sm := sm + 1;
        }
        i := i + 1;
    }
    s := cap - sm;
}
